#!/usr/bin/env bash
# 000-z-rg2-a -- TESTE SEM INSTALAR da V1.0.289 (regimento 2.0 do hotel boutique, 7 idiomas), sobre o main da fila (1.0.288, a76af0e).
# Copia do main da fila em /tmp, aplica o pacote, roda a suite inteira e a prova real no banco DESCARTAVEL de prova
# (o mesmo que o subir-v1.sh cria e apaga). Nao mexe no codigo instalado, no banco de producao, nos servicos nem na fila.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v289t.XXXX)
echo "" | base64 -d > $T/p.patch.gz
echo "abe93d2a35bfbe15b5b15585b4d6ba3ac1dd47e29b1f0de5c217ce00861a980e  $T/p.patch.gz" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
gzip -dc $T/p.patch.gz > $T/p.patch
G="git -c safe.directory=* -C /opt/pms-banana-ai-fila.git"
MAIN=$($G rev-parse --short main); echo "main da fila: $MAIN (esperado a76af0e = 1.0.288)"
mkdir -p $T/repo && $G archive main SISTEMA | tar -x -C $T/repo
cd $T/repo && echo "copia: $(grep -oP 'VERSAO = "\K[^"]+' SISTEMA/api/app/versao.py)"
patch -p1 --dry-run -s --no-backup-if-mismatch < $T/p.patch && patch -p1 -s --no-backup-if-mismatch < $T/p.patch && echo "pacote 289 aplicado" || { echo "PATCH NAO APLICA (o main andou? refazer o pacote sobre o main novo)"; rm -rf $T; exit 1; }
SYS=$T/repo/SISTEMA; cd $SYS && ln -s /opt/PMS-Banana-AI/SISTEMA/.venv .venv
P() { env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 900 .venv/bin/pytest -o addopts="-p no:cacheprovider" "$@" 2>&1; }
echo "== testes do regimento"; P -q api/app/reservation/tests/test_v1289_regimento_20.py api/app/reservation/tests/test_v1253_regimento_18_airbnb.py api/app/reservation/tests/test_v1174_regimento_dress_code.py | tail -3
echo "== suite inteira"; P -q --maxfail=80 api | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed|error)' | tail -40 | cut -c1-220
echo "== prova real (banco descartavel pms_banana_ai_prova)"
DB_PASSWORD=$(grep -E '^DB_PASSWORD=' /etc/pms-banana-ai/secrets.env | head -1 | cut -d= -f2- | tr -d '"'"'"'')
DB_PROVA=pms_banana_ai_prova
mysql -e "DROP DATABASE IF EXISTS $DB_PROVA; CREATE DATABASE $DB_PROVA CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;" \
 && env -i PATH="$PATH" HOME=/root LANG=C.UTF-8 .venv/bin/python ops/apply_migration.py --dsn "mysql://pms:$DB_PASSWORD@127.0.0.1:3306/$DB_PROVA" --dir migrations >/dev/null 2>&1 \
 && PROVA=$(env -i PATH="$PATH" HOME=/root LANG=C.UTF-8 .venv/bin/python ops/prova_real.py --dsn "mysql://pms:$DB_PASSWORD@127.0.0.1:3306/$DB_PROVA" 2>&1)
echo "$PROVA" | grep -E '"ok": false|"resumo"' | sed -E 's/(mysql:\/\/[^@]*@)/mysql:\/\/***@/g' | tail -15 | cut -c1-240
mysql -e "DROP DATABASE IF EXISTS $DB_PROVA;"
unset DB_PASSWORD PROVA
echo "== a pagina /regimento nos 7 idiomas (copia, sem banco)"
cd $SYS/api && env -i PATH=/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 120 ../.venv/bin/python -c "
from app.reservation import regimento as RG
print('VERSAO', RG.VERSAO, {l: RG.pagina(l).count('<h2>') for l in ('pt','en','es','fr','de','ja','zh')})"
rm -rf $T
echo "FIM: nada instalado. Instalar so com 'instala 289' do Dom."
